/**
 * Hacker News truncates the visible text of long links in comments, keeping only a prefix of
 * the url and appending an ellipsis, while the {@code href} attribute keeps the full url. That
 * is fine when simply reading a comment, but it means the full link cannot be selected or
 * copied. This replaces such truncated link texts with the complete url from the href.
 * <p>
 * Link texts which are not just a shortened version of their href (regular, descriptive link
 * texts) are left untouched.
 */
public static String expandTruncatedLinks(String html) {
    if (TextUtils.isEmpty(html)) {
        return html;
    }

    Matcher matcher = A_TAG_PATTERN.matcher(html);
    StringBuffer result = new StringBuffer();

    while (matcher.find()) {
        String openingTag = matcher.group(1);
        String href = matcher.group(2);
        String linkText = matcher.group(3);
        String closingTag = matcher.group(4);

        String expandedText = isTruncatedVersionOf(linkText, href) ? href : linkText;

        matcher.appendReplacement(result,
                Matcher.quoteReplacement(openingTag + expandedText + closingTag));
    }
    matcher.appendTail(result);

    return result.toString();
}

/**
 * Whether {@code linkText} looks like an ellipsized version of {@code href}, i.e. a prefix of
 * the url followed by an ellipsis. Both are compared in their html escaped form, which is
 * consistent since they originate from the same document.
 */
private static boolean isTruncatedVersionOf(String linkText, String href) {
    if (TextUtils.isEmpty(linkText) || TextUtils.isEmpty(href)) {
        return false;
    }

    String prefix = null;
    for (String ellipsis : ELLIPSES) {
        if (linkText.endsWith(ellipsis)) {
            prefix = linkText.substring(0, linkText.length() - ellipsis.length());
            break;
        }
    }

    if (TextUtils.isEmpty(prefix) || href.length() <= prefix.length()) {
        return false;
    }

    if (href.startsWith(prefix)) {
        return true;
    }

    // The displayed text sometimes omits the scheme even though the href includes it
    for (String scheme : SCHEMES) {
        if (href.startsWith(scheme) && href.substring(scheme.length()).startsWith(prefix)) {
            return true;
        }
    }

    return false;
}

